import type { ButtonHTMLAttributes } from 'react'

type Props = ButtonHTMLAttributes<HTMLButtonElement> & { variant?: 'primary' | 'ghost'; full?: boolean }

export function Button({ variant = 'primary', full, className = '', ...rest }: Props) {
  return <button className={`btn btn-${variant} ${full ? 'btn-full' : ''} ${className}`} {...rest} />
}
